export type PromptTier = "free" | "pro";

export interface Prompt {
  /** Уникальный slug в пределах категории — для якорей и будущих ссылок. */
  id: string;
  category: CategorySlug;
  title: string;
  /** Короткое описание задачи, которую решает промт. */
  summary: string;
  tier: PromptTier;
  /** Лучшая нейросеть под эту задачу. */
  bestFor: string;
  tags: string[];
  /** Текст промта. {переменные} — то, что пользователь заменяет под себя. */
  prompt: string;
  /** Пример результата / что получите на выходе. */
  example: string;
}

