    tier: "free",
    bestFor: "Midjourney / ChatGPT (vision)",
    tags: ["иллюстрация", "стиль", "набор"],
    prompt: `Ты — арт-директор. Опиши стиль иллюстраций для продукта.

Продукт: {что это}
Где будут картинки: {пустые экраны, блог, письма, соцсети}
Настроение: {три слова}
Палитра: {цвета}

Задай правила:
1. Толщина линии, наличие обводки, заливка — плоская или с текстурой.
2. Люди: есть или нет. Если есть — насколько условные. Реалистичные лица стареют быстрее всего и первыми выдают дату.
3. Перспектива: фронтально, изометрия, вид сверху. Одна на весь набор.
4. Сколько цветов на одной картинке — потолком, а не пожеланием.
5. Что делает картинка: поясняет, украшает или ведёт взгляд. От этого зависит уровень детализации.
6. Три готовых промта, показывающих диапазон: простая, средняя, сложная сцена.
7. Проверка на новую картинку: три вопроса, по которым видно, что она из набора.

Правила должен уметь применить другой человек. «Дружелюбно и современно» применить нельзя.`,
    example: `Линия 2px, обводки нет, заливка плоская с зерном 6%.
Люди условные: голова — круг без черт лица. Реалистичные лица через год выглядят как клипарт нулевых.
Изометрия, угол 30°, одна на весь набор. Цветов не больше четырёх плюс фон.
Проверка: линия одной толщины? Угол тот же? Цветов не больше четырёх?`,
